# @@ imports
# @@ data: points near the line y = 1 + 2 x
X = [[1.0, 0.0], [1.0, 0.5], [1.0, 1.0], [1.0, 1.5], [1.0, 2.0]]
y = [1.1, 1.9, 3.2, 3.9, 5.1]
# @@ the loss
def loss(w: Arr, X: Arr, y: Arr) {
    r = py_bsub(X @ w, y)
    return py_div_f(py_npsum(r * r), len(y))
}
# @@ its gradient
def loss_grad(w: Arr, X: Arr, y: Arr) {
    r = py_bsub(X @ w, y)
    return 2.0 * (transpose(X) @ r) / len(y)
}
# @@ check the gradient at one point
w0 = [0.5, 0.5]
H = 1e-06
py_s2 = eye(2, 2, 0)
py_l1 = zeros(len(py_s2))
for py_i3 to len(py_s2) {
    py_e4 = slab(py_s2, py_i3)
    py_l1[py_i3] = py_div_f(loss(py_badd(w0, H * py_e4), X, y) - loss(py_bsub(w0, H * py_e4), X, y), 2 * H)
}
fd = py_l1
py_l5 = []
py_s6 = loss_grad(w0, X, y)
for py_i7 to len(py_s6) {
    py_g8 = py_s6[py_i7]
    py_l5 = append(py_l5, fmt(py_g8, ".6f"))
}
print("gradient   ", join(" ", py_l5))
print("differences", join(" ", [fmt(py_g11, ".6f") for py_g11 in fd]))
# @@ gradient descent
RATE = 0.1
STEPS = 500
REPORT = 100
w = py_copy(w0)
for step to STEPS {
    w = py_bsub(w, RATE * loss_grad(w, X, y))
    if py_mod_i(py_int(step + 1), REPORT) == 0 {
        print("step ", fmt((py_int(step + 1)) + 0.0, "d"), ": loss ", fmt(loss(w, X, y), ".8f"), sep="")
    }
}
print("w = ", fmt(w[0], ".6f"), ", ", fmt(w[1], ".6f"), sep="")
# @@ a derivative of one variable
def f(x) {
    return sin(x) * x * x
}
def df(x) {
    return cos(x) * x * x + 2.0 * x * sin(x)
}
print("f'(1.3) =", fmt(df(1.3), ".12f"))
# @@ checks
if not (py_ballclose(loss_grad(w0, X, y), fd, 1e-05, 1e-06)) {
    stop("AssertionError")
}
